mapper.select:
SELECT MAIN.*, CU.AI_INPT_CMN_CD_ENG_NM AS CUCD, BIZ.AI_INPT_CMN_CD_NM AS INPT_ATMC_BIZ_NM, BIZ.AI_INPT_CMN_CD AS REQ_DSCD, BIZ.AI_INPT_CMN_CD_NM, NM.AI_INPT_CMN_CD_NM AS STAT_NM FROM( SELECT NULL AS INPT_MST_SRNO, A.FX_ACNO AS FX, A.XPO_CVRG_MTBR_MK_DT AS DT, A.XPBY_COL_CTR_CUCD AS CUCD1, A.TRN_OPR_NO AS OPR, A.CUS_KORL_NM AS CUS, A.INPT_ATMC_BIZ_DSCD AS BIZ_DSCD, A.INPT_ATMC_REQ_DSCD AS INPT_ATMC_REQ_DSCD, '10' AS AI_INSP_ATVT_STS_CD, A.KRBR_NM AS BZBR_NM, A.XPBY_COL_AM AS AM, A.CSNO AS CSNO, A.XPO_CVRG_MK_SQ AS FX_REFNO_SRNO FROM CSPD201TM A WHERE NOT EXISTS ( SELECT ACTL_FX_REFNO, FX_REFNO_SRNO FROM CSPD001TM WHERE ACTL_FX_REFNO = A.FX_ACNO AND FX_REFNO_SRNO = A.XPO_CVRG_MK_SQ ) /*검색조건 : 업무생성일*/ AND A.XPO_CVRG_MTBR_MK_DT = REPLACE(#{inptRcpDt}, '-', '')
/*검색조건 : 고객번호*/ AND A.CSNO = #{aiInptCusNo}
/*검색조건 : 수출입업무구분*/ AND A.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd}
/*검색조건 : Ref.No*/ AND A.FX_ACNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
UNION ALL
SELECT NULL AS INPT_MST_SRNO, A.FX_ACNO AS FX, A.TDOC_RCP_DT AS DT, A.TDOC_RCP_CUCD AS CUCD1, A.TRN_OPR_NO AS OPR, A.CUS_KORL_NM AS CUS, A.INPT_ATMC_BIZ_DSCD AS BIZ_DSCD, A.INPT_ATMC_REQ_DSCD AS INPT_ATMC_REQ_DSCD, '10' AS AI_INSP_ATVT_STS_CD, A.KRBR_NM AS BZBR_NM, A.TDOC_RCP_AM AS AM, A.CSNO AS CSNO, A.TDOC_RCP_SRNO AS FX_REFNO_SRNO FROM CSPD202TM A WHERE NOT EXISTS ( SELECT ACTL_FX_REFNO, FX_REFNO_SRNO FROM CSPD001TM WHERE ACTL_FX_REFNO = A.FX_ACNO AND FX_REFNO_SRNO = A.TDOC_RCP_SRNO ) /*검색조건 : 업무생성일*/ AND A.TDOC_RCP_DT = REPLACE(#{inptRcpDt}, '-', '')
/*검색조건 : 고객번호*/ AND A.CSNO = #{aiInptCusNo}
/*검색조건 : 수출입업무구분*/ AND A.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd}
/*검색조건 : Ref.No*/ AND A.FX_ACNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
UNION ALL SELECT M.INPT_MST_SRNO , E.FX_ACNO AS FX , E.XPO_CVRG_MTBR_MK_DT AS DT , E.XPBY_COL_CTR_CUCD AS CUCD1 , E.TRN_OPR_NO AS OPR , E.CUS_KORL_NM AS CUS , E.INPT_ATMC_BIZ_DSCD AS BIZ_DSCD , E.INPT_ATMC_REQ_DSCD as INPT_ATMC_REQ_DSCD , '60' AS AI_INSP_ATVT_STS_CD , E.KRBR_NM AS BZBR_NM , E.XPBY_COL_AM AS AM , E.CSNO AS CSNO , E.XPO_CVRG_MK_SQ AS FX_REFNO_SRNO FROM CSPD001TM M ,CSPD201TM E WHERE M.ACTL_FX_REFNO = E.FX_ACNO AND M.FX_REFNO_SRNO = E.XPO_CVRG_MK_SQ AND M.PAPS_RE_SCAN_NED_YN = 'Y' AND M.PAPS_RE_SCAN_CMPL_YN IS NULL /*검색조건 : 업무생성일*/ AND E.XPO_CVRG_MTBR_MK_DT = REPLACE(#{inptRcpDt}, '-', '')
/*검색조건 : 고객번호*/ AND E.CSNO = #{aiInptCusNo}
/*검색조건 : 수출입업무구분*/ AND E.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd}
/*검색조건 : Ref.No*/ AND E.FX_ACNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
UNION ALL SELECT M.INPT_MST_SRNO , E.FX_ACNO AS FX , E.TDOC_RCP_DT AS DT , E.TDOC_RCP_CUCD AS CUCD1 , E.TRN_OPR_NO AS OPR , E.CUS_KORL_NM AS CUS , E.INPT_ATMC_BIZ_DSCD AS BIZ_DSCD , E.INPT_ATMC_REQ_DSCD as INPT_ATMC_REQ_DSCD , '60' AS AI_INSP_ATVT_STS_CD , E.KRBR_NM AS BZBR_NM , E.TDOC_RCP_AM AS AM , E.CSNO AS CSNO , E.TDOC_RCP_SRNO AS FX_REFNO_SRNO FROM CSPD001TM M ,CSPD202TM E WHERE M.ACTL_FX_REFNO = E.FX_ACNO AND M.FX_REFNO_SRNO = E.TDOC_RCP_SRNO AND M.PAPS_RE_SCAN_NED_YN = 'Y' AND M.PAPS_RE_SCAN_CMPL_YN IS NULL /*검색조건 : 업무생성일*/ AND E.TDOC_RCP_DT = REPLACE(#{inptRcpDt}, '-', '')
/*검색조건 : 고객번호*/ AND E.CSNO = #{aiInptCusNo}
/*검색조건 : 수출입업무구분*/ AND E.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd}
/*검색조건 : Ref.No*/ AND E.FX_ACNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
)MAIN , CSPD112TI NM , CSPD112TI CU , CSPD112TI BIZ WHERE NM.AI_INPT_GRP_CD = '300' AND NM.AI_INPT_CMN_CD = MAIN.AI_INSP_ATVT_STS_CD AND CU.AI_INPT_GRP_CD = '270' AND CU.AI_INPT_CMN_CD = MAIN.CUCD1 AND BIZ.AI_INPT_GRP_CD = '150' AND BIZ.AI_INPT_CMN_CD = MAIN.BIZ_DSCD
/*검색조건 : 신규 혹은 재스캔 생성구분*/ AND MAIN.AI_INSP_ATVT_STS_CD = #{aiInspAtvtStsCd}
ORDER BY DT
ORDER BY DT DESC
ORDER BY BIZ_DSCD
ORDER BY BIZ_DSCD DESC
ORDER BY STAT_NM
ORDER BY STAT_NM DESC
ORDER BY FX
ORDER BY FX DESC
ORDER BY CUCD
ORDER BY CUCD DESC
ORDER BY AM
ORDER BY AM DESC
ORDER BY CUS
ORDER BY CUS DESC
ORDER BY OPR
ORDER BY OPR DESC
ORDER BY BZBR_NM
ORDER BY BZBR_NM DESC
ORDER BY INPT_ATMC_REQ_DSCD
ORDER BY INPT_ATMC_REQ_DSCD DESC
ORDER BY DT DESC

/* RevertTodoMapper.selectListTotCnt */ SELECT COUNT(*) FROM( SELECT NULL AS INPT_MST_SRNO, A.FX_ACNO AS FX, A.XPO_CVRG_MTBR_MK_DT AS DT, A.XPBY_COL_CTR_CUCD AS CUCD1, A.TRN_OPR_NO AS OPR, A.CUS_KORL_NM AS CUS, A.INPT_ATMC_BIZ_DSCD AS BIZ_DSCD, A.INPT_ATMC_REQ_DSCD AS INPT_ATMC_REQ_DSCD, '10' AS AI_INSP_ATVT_STS_CD, A.KRBR_NM AS BZBR_NM, A.XPBY_COL_AM AS AM, A.CSNO AS CSNO, A.XPO_CVRG_MK_SQ AS FX_REFNO_SRNO FROM CSPD201TM A WHERE NOT EXISTS ( SELECT ACTL_FX_REFNO, FX_REFNO_SRNO FROM CSPD001TM WHERE ACTL_FX_REFNO = A.FX_ACNO AND FX_REFNO_SRNO = A.XPO_CVRG_MK_SQ ) /*검색조건 : 업무생성일*/ AND A.XPO_CVRG_MTBR_MK_DT = REPLACE(#{inptRcpDt}, '-', '')
/*검색조건 : 고객번호*/ AND A.CSNO = #{aiInptCusNo}
/*검색조건 : 수출입업무구분*/ AND A.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd}
/*검색조건 : Ref.No*/ AND A.FX_ACNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
UNION ALL
SELECT NULL AS INPT_MST_SRNO, A.FX_ACNO AS FX, A.TDOC_RCP_DT AS DT, A.TDOC_RCP_CUCD AS CUCD1, A.TRN_OPR_NO AS OPR, A.CUS_KORL_NM AS CUS, A.INPT_ATMC_BIZ_DSCD AS BIZ_DSCD, A.INPT_ATMC_REQ_DSCD AS INPT_ATMC_REQ_DSCD, '10' AS AI_INSP_ATVT_STS_CD, A.KRBR_NM AS BZBR_NM, A.TDOC_RCP_AM AS AM, A.CSNO AS CSNO, A.TDOC_RCP_SRNO AS FX_REFNO_SRNO FROM CSPD202TM A WHERE NOT EXISTS ( SELECT ACTL_FX_REFNO, FX_REFNO_SRNO FROM CSPD001TM WHERE ACTL_FX_REFNO = A.FX_ACNO AND FX_REFNO_SRNO = A.TDOC_RCP_SRNO ) /*검색조건 : 업무생성일*/ AND A.TDOC_RCP_DT = REPLACE(#{inptRcpDt}, '-', '')
/*검색조건 : 고객번호*/ AND A.CSNO = #{aiInptCusNo}
/*검색조건 : 수출입업무구분*/ AND A.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd}
/*검색조건 : Ref.No*/ AND A.FX_ACNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
UNION ALL SELECT M.INPT_MST_SRNO , E.FX_ACNO AS FX , E.XPO_CVRG_MTBR_MK_DT AS DT , E.XPBY_COL_CTR_CUCD AS CUCD1 , E.TRN_OPR_NO AS OPR , E.CUS_KORL_NM AS CUS , E.INPT_ATMC_BIZ_DSCD AS BIZ_DSCD , E.INPT_ATMC_REQ_DSCD as INPT_ATMC_REQ_DSCD , '60' AS AI_INSP_ATVT_STS_CD , E.KRBR_NM AS BZBR_NM , E.XPBY_COL_AM AS AM , E.CSNO AS CSNO , E.XPO_CVRG_MK_SQ AS FX_REFNO_SRNO FROM CSPD001TM M ,CSPD201TM E WHERE M.ACTL_FX_REFNO = E.FX_ACNO AND M.FX_REFNO_SRNO = E.XPO_CVRG_MK_SQ AND M.PAPS_RE_SCAN_NED_YN = 'Y' AND M.PAPS_RE_SCAN_CMPL_YN IS NULL /*검색조건 : 업무생성일*/ AND E.XPO_CVRG_MTBR_MK_DT = REPLACE(#{inptRcpDt}, '-', '')
/*검색조건 : 고객번호*/ AND E.CSNO = #{aiInptCusNo}
/*검색조건 : 수출입업무구분*/ AND E.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd}
/*검색조건 : Ref.No*/ AND E.FX_ACNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
UNION ALL SELECT M.INPT_MST_SRNO , E.FX_ACNO AS FX , E.TDOC_RCP_DT AS DT , E.TDOC_RCP_CUCD AS CUCD1 , E.TRN_OPR_NO AS OPR , E.CUS_KORL_NM AS CUS , E.INPT_ATMC_BIZ_DSCD AS BIZ_DSCD , E.INPT_ATMC_REQ_DSCD as INPT_ATMC_REQ_DSCD , '60' AS AI_INSP_ATVT_STS_CD , E.KRBR_NM AS BZBR_NM , E.TDOC_RCP_AM AS AM , E.CSNO AS CSNO , E.TDOC_RCP_SRNO AS FX_REFNO_SRNO FROM CSPD001TM M ,CSPD202TM E WHERE M.ACTL_FX_REFNO = E.FX_ACNO AND M.FX_REFNO_SRNO = E.TDOC_RCP_SRNO AND M.PAPS_RE_SCAN_NED_YN = 'Y' AND M.PAPS_RE_SCAN_CMPL_YN IS NULL /*검색조건 : 업무생성일*/ AND E.TDOC_RCP_DT = REPLACE(#{inptRcpDt}, '-', '')
/*검색조건 : 고객번호*/ AND E.CSNO = #{aiInptCusNo}
/*검색조건 : 수출입업무구분*/ AND E.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd}
/*검색조건 : Ref.No*/ AND E.FX_ACNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
)MAIN , CSPD112TI NM , CSPD112TI CU , CSPD112TI BIZ WHERE NM.AI_INPT_GRP_CD = '300' AND NM.AI_INPT_CMN_CD = MAIN.AI_INSP_ATVT_STS_CD AND CU.AI_INPT_GRP_CD = '270' AND CU.AI_INPT_CMN_CD = MAIN.CUCD1 AND BIZ.AI_INPT_GRP_CD = '150' AND BIZ.AI_INPT_CMN_CD = MAIN.BIZ_DSCD
/*검색조건 : 신규 혹은 재스캔 생성구분*/ AND MAIN.AI_INSP_ATVT_STS_CD = #{aiInspAtvtStsCd}
